"""Settings shim for the vendored ai-sales-agent renderer (render.py expects a pydantic
`settings` object from `sales_agent.config`).  RevenueOS supplies the same attribute
names from revenueos.yaml so the vendored code runs unmodified.  This file is owned by
RevenueOS, not regenerated by scripts/vendor.py."""
from __future__ import annotations

from functools import cached_property
from typing import Any

import yaml

from revenueos.paths import Workspace


class _Settings:
    @cached_property
    def _cfg(self) -> dict[str, Any]:
        ws = Workspace.locate()
        if ws.config.exists():
            return yaml.safe_load(ws.config.read_text()) or {}
        return {}

    def reload(self) -> None:
        self.__dict__.pop("_cfg", None)

    @property
    def booking_url(self) -> str | None:
        return self._cfg.get("booking_url") or None

    @property
    def booking_duration_min(self) -> int:
        return int(self._cfg.get("booking_duration_min", 20))

    @property
    def casl_sender_name(self) -> str:
        return (self._cfg.get("sender") or {}).get("name") or self._cfg.get("company_name") or "RevenueOS user"

    @property
    def casl_sender_address(self) -> str:
        return (self._cfg.get("sender") or {}).get("postal_address") or ""

    @property
    def gmail_sender_email(self) -> str:
        return (self._cfg.get("sender") or {}).get("email") or ""


settings = _Settings()
